-- ort-db-10.sql – Schema + Daten fuer die MySQL-Ortsdatenbank (Endpunkt ort-db.php).
-- Import:  mysql -u USER -p DATENBANK < ort-db-10.sql   (phpMyAdmin; evtl. max_allowed_packet erhoehen)
-- Alle GeoNames-Siedlungen >= 10 Einw. (allCountries, Feature-Klasse P, population >= 10)
--   plus alle Eintraege aus ort-db.sql (>= 50 Einw. inkl. kuratierter Orte/deutscher Namen).
-- Lizenz: GeoNames CC BY 4.0, Natural Earth public domain.
CREATE DATABASE IF NOT EXISTS notfallblatt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE notfallblatt;
DROP TABLE IF EXISTS orte;
CREATE TABLE orte (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  lat DECIMAL(8,5) NOT NULL,
  lon DECIMAL(9,5) NOT NULL,
  cc CHAR(2) NOT NULL,
  KEY idx_cc (cc),
  KEY idx_lat (lat),
  KEY idx_lon (lon)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
